import * as THREE from '../vendor/three.module.js';import {LOCAL_LIFT} from './local-lift-config.js';import {LEVELS,LANDING,SHAFT,HEIGHT} from './architecture.js';import {CABIN,fixedWalls} from './simulation.js';import {exposeBoxSurfaces} from './surfaces.js';
export function installLocalLiftView(View){View.prototype.buildLocalLift=function(){const dx=LOCAL_LIFT.offset.x,dz=LOCAL_LIFT.offset.z;
 for(const y of LOCAL_LIFT.levels){const i=LEVELS.indexOf(y),g=new THREE.Group();g.position.set(dx,y,dz);this.fixed.add(g);this.fixedFloors.push({g,y});this.cube(g,LANDING.x,0,2,2,.16,4,'#b7c2aa');this.cube(g,-2.65,0,2.4,.25,.16,3.2,'metal');for(const l of fixedWalls())this.wall(g,l,2.8);this.roofs.push(this.cube(g,LANDING.x,2.96,2,2,.16,4,'#c9d0ba'));this.wall(g,{a:[-.46,3],b:[-.46,5]},.3,'wall',.12,2.66);this.wall(g,{a:[-2.34,2.4],b:[-2.34,5.6]},.2,'wall',.12,2.76);this.shutters.push({mesh:this.cube(g,-.52,.16,3,.12,2.5,2,'metal'),landing:'LF'+i});const mask=new THREE.Group();g.add(mask);this.fixedMaskGroups['LF'+i]=mask;}
 const shaft=new THREE.Group();shaft.position.set(dx,0,dz);this.fixed.add(shaft);this.localShaft=shaft;const min=Math.min(...LOCAL_LIFT.levels)-.2,max=Math.max(...LOCAL_LIFT.levels)+HEIGHT+.2,h=max-min;this.cube(shaft,SHAFT.x,min,SHAFT.z,.2,h,4.4,'concrete');this.cube(shaft,SHAFT.x,min,SHAFT.z,4.4,h,.2,'concrete');this.cube(shaft,SHAFT.x,min,6,4.4,h,.2,'concrete');this.cube(shaft,SHAFT.x,max-.2,SHAFT.z,4.4,.2,4.4,'concrete');this.cube(shaft,SHAFT.x,min,SHAFT.z,4.4,.2,4.4,'concrete');for(const[z,d]of[[1.8,.6],[5.6,.6]])this.cube(shaft,-2.6,min,z,.2,h,d,'concrete');let at=min;for(const y of LOCAL_LIFT.levels){this.cube(shaft,-2.6,at,2.4,.2,y+.16-at,3.2,'concrete');at=y+2.76;}this.cube(shaft,-2.6,at,2.4,.2,max-at,3.2,'concrete');for(const y of LOCAL_LIFT.levels)this.shutters.push({mesh:this.cube(shaft,-2.56,y+.16,2.4,.12,2.6,3.2,'metal'),lift:true,liftId:'local',y});
 const cabin=new THREE.Group();cabin.position.set(dx,this.sim.localLift.liftY,dz);this.scene.add(cabin);this.localCabin=cabin;this.cube(cabin,CABIN.x,0,CABIN.z,CABIN.w,.16,CABIN.d,'#b7ad82');for(const l of[{a:[CABIN.x+.06,CABIN.z],b:[CABIN.x+.06,CABIN.z+CABIN.d]},{a:[CABIN.x,CABIN.z+.06],b:[CABIN.x+CABIN.w,CABIN.z+.06]},{a:[CABIN.x,CABIN.z+CABIN.d-.06],b:[CABIN.x+CABIN.w,CABIN.z+CABIN.d-.06]},{a:[-2.71,2.05],b:[-2.71,2.4]},{a:[-2.71,5.6],b:[-2.71,5.95]}])this.wall(cabin,l,2.8,'metal');this.wall(cabin,{a:[-2.71,2.4],b:[-2.71,5.6]},.2,'metal',.12,2.76);this.localCabinDoor=this.cube(cabin,-2.77,.16,2.4,.12,2.6,3.2,'metal');this.roofs.push(this.cube(cabin,CABIN.x,2.96,CABIN.z,CABIN.w,.16,CABIN.d,'#abb8a9'));this.text(cabin,'居住区 EV  /  E',CABIN.x+.13,2.25,4,{size:.35,rotation:Math.PI/2});exposeBoxSurfaces(cabin,new Set([this.localCabinDoor]));
 };View.prototype.renderLocalLift=function(){const c=this.sim.localLift;this.localCabin.position.y=c.liftY;const amount=c.liftActive&&c.liftState==='open'?1:c.liftGate;this.localCabinDoor.visible=amount>.001;this.localCabinDoor.scale.y=Math.max(.001,amount);this.localCabinDoor.position.y=.16+2.6-1.3*amount;};}
